public async Task UpdatePostTitleAsync(
    BlogContext context,
    int postId,
    string newTitle,
    CancellationToken cancellationToken)
{
    var postQuery =
        from post in context.Posts
        where post.Id == postId
        select post;

    var matchingPost = await postQuery.SingleOrDefaultAsync(cancellationToken);

    if (matchingPost is null)
    {
        throw new InvalidOperationException($"Post {postId} was not found.");
    }

    matchingPost.Title = newTitle;

    await context.SaveChangesAsync(cancellationToken);
}
